use ctrlrt::k8s_openapi::ByteString;
use ctrlrt::k8s_openapi::api::apps::v1::DaemonSet;
use ctrlrt::k8s_openapi::api::core::v1::{
    Container, Namespace, PodSpec, ResourceRequirements, Secret, Toleration,
};
use ctrlrt::k8s_openapi::apimachinery::pkg::api::resource::Quantity;
use ctrlrt::k8s_openapi::apimachinery::pkg::apis::meta::v1::{LabelSelector, ObjectMeta};
use ctrlrt::log::{KeyValues, LogSink, Logger};
use ctrlrt::{Ctx, Result};
use ctrlrt_fake::{FakeClientBuilder, FakeClientset, FakeClientsetBuilder, Reaction, Scheme};
use hostedclient::{ClientManager, HostedClient};
use registry::authn::Keychain;
