const CR_NAMESPACE: &str = "test-ns";
const CR_NAME: &str = "test";

// --- fixture ----------------------------------------------------------------------------------

#[derive(Debug, Deserialize)]
struct ReaderResult {
    image: String,
    #[serde(default)]
    err: String,
}

#[derive(Clone, Debug, Deserialize)]
struct Fail {
    verb: String,
    resource: String,
    message: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Step {
    size: String,
    amount: i32,
    release: String,
    fail: Option<Fail>,
    #[serde(default)]
    reinject: bool,
    replace_namespace: Option<Value>,
    replace_daemon_set: Option<Value>,

    error: String,
    panic: bool,
    cached: bool,
    reader_calls: Option<Vec<String>>,
    logs: Option<Vec<String>>,
    namespace: String,
    daemon_set: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Scenario {
    pull_secret: String,
    inject_client: bool,
    reader: BTreeMap<String, ReaderResult>,
    #[serde(default)]
    seed_namespaces: Vec<Value>,
    steps: Vec<Step>,
}

fn fixture(name: &str) -> Scenario {
    let path = format!("{}/tests/fixtures/{name}.json", env!("CARGO_MANIFEST_DIR"));
    let s = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&s).unwrap()
}

// --- Go encoding of the hosted objects ----------------------------------------------------

fn is_false(b: &bool) -> bool {
    !*b
}
fn is_zero_i32(v: &i32) -> bool {
    *v == 0
}
fn is_zero_i64(v: &i64) -> bool {
    *v == 0
}
fn opt_str_empty(s: &Option<String>) -> bool {
    s.as_deref().unwrap_or("").is_empty()
}
fn opt_vec_empty<T>(v: &Option<Vec<T>>) -> bool {
    v.as_ref().is_none_or(|v| v.is_empty())
}
fn opt_map_empty<V>(m: &Option<BTreeMap<String, V>>) -> bool {
    m.as_ref().is_none_or(|m| m.is_empty())
}

/// `corev1.Namespace`
#[derive(Serialize)]
struct GoNamespace<'a> {
    metadata: apis::go::Go<'a, ObjectMeta>,
    spec: GoNamespaceSpec<'a>,
    status: GoNamespaceStatus<'a>,
}
#[derive(Serialize)]
struct GoNamespaceSpec<'a> {
    #[serde(skip_serializing_if = "opt_vec_empty")]
    finalizers: &'a Option<Vec<String>>,
}
#[derive(Serialize)]
struct GoNamespaceStatus<'a> {
    #[serde(skip_serializing_if = "opt_str_empty")]
    phase: &'a Option<String>,
    #[serde(skip_serializing_if = "opt_vec_empty")]
    conditions: Option<Vec<Value>>,
}

fn go_namespace(ns: &Namespace) -> String {
    let spec = ns.spec.clone().unwrap_or_default();
    let status = ns.status.clone().unwrap_or_default();
    let out = serde_json::to_string(&GoNamespace {
        metadata: apis::go::Go(&ns.metadata),
        spec: GoNamespaceSpec {
            finalizers: &spec.finalizers,
        },
        status: GoNamespaceStatus {
            phase: &status.phase,
            conditions: status
                .conditions
                .as_ref()
                .map(|c| c.iter().map(|c| serde_json::to_value(c).unwrap()).collect()),
        },
    })
    .unwrap();
    assert_lossless::<Namespace>(ns, &out);
    out
}

/// `appsv1.DaemonSet`
#[derive(Serialize)]
struct GoDaemonSet<'a> {
    metadata: apis::go::Go<'a, ObjectMeta>,
    spec: GoDaemonSetSpec<'a>,
    status: GoDaemonSetStatus,
}
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct GoDaemonSetSpec<'a> {
    selector: GoLabelSelector<'a>,
    template: GoPodTemplateSpec<'a>,
    update_strategy: GoUpdateStrategy,
    #[serde(skip_serializing_if = "is_zero_i32")]
    min_ready_seconds: i32,
    #[serde(skip_serializing_if = "Option::is_none")]
    revision_history_limit: Option<i32>,
}
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct GoLabelSelector<'a> {
    #[serde(skip_serializing_if = "opt_map_empty")]
    match_labels: &'a Option<BTreeMap<String, String>>,
    #[serde(skip_serializing_if = "opt_vec_empty")]
    match_expressions: Option<Vec<Value>>,
}
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct GoUpdateStrategy {
    #[serde(rename = "type", skip_serializing_if = "opt_str_empty")]
    type_: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    rolling_update: Option<Value>,
}
#[derive(Serialize)]
struct GoPodTemplateSpec<'a> {
    metadata: apis::go::Go<'a, ObjectMeta>,
    spec: GoPodSpec<'a>,
}
/// The `corev1.PodSpec` fields (Go order) the fixtures use; [`assert_lossless`] catches any
/// other field.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct GoPodSpec<'a> {
    containers: Option<Vec<GoContainer<'a>>>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    restart_policy: &'a Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    termination_grace_period_seconds: Option<i64>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    dns_policy: &'a Option<String>,
    #[serde(skip_serializing_if = "opt_map_empty")]
    node_selector: &'a Option<BTreeMap<String, String>>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    service_account_name: &'a Option<String>,
    #[serde(skip_serializing_if = "is_false")]
    host_network: bool,
    #[serde(skip_serializing_if = "opt_str_empty")]
    scheduler_name: &'a Option<String>,
    #[serde(skip_serializing_if = "opt_vec_empty")]
    tolerations: Option<Vec<GoToleration<'a>>>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    priority_class_name: &'a Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    priority: Option<i32>,
}
/// The `corev1.Container` fields (Go order) the fixtures use.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct GoContainer<'a> {
    name: &'a str,
    #[serde(skip_serializing_if = "opt_str_empty")]
    image: &'a Option<String>,
    #[serde(skip_serializing_if = "opt_vec_empty")]
    command: &'a Option<Vec<String>>,
    #[serde(skip_serializing_if = "opt_vec_empty")]
    args: &'a Option<Vec<String>>,
    resources: GoResources<'a>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    termination_message_path: &'a Option<String>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    termination_message_policy: &'a Option<String>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    image_pull_policy: &'a Option<String>,
}
#[derive(Serialize)]
struct GoResources<'a> {
    #[serde(skip_serializing_if = "opt_map_empty")]
    limits: &'a Option<BTreeMap<String, Quantity>>,
    #[serde(skip_serializing_if = "opt_map_empty")]
    requests: &'a Option<BTreeMap<String, Quantity>>,
}
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct GoToleration<'a> {
    #[serde(skip_serializing_if = "opt_str_empty")]
    key: &'a Option<String>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    operator: &'a Option<String>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    value: &'a Option<String>,
    #[serde(skip_serializing_if = "opt_str_empty")]
    effect: &'a Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    toleration_seconds: Option<i64>,
}
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct GoDaemonSetStatus {
    current_number_scheduled: i32,
    number_misscheduled: i32,
    desired_number_scheduled: i32,
    number_ready: i32,
    #[serde(skip_serializing_if = "is_zero_i64")]
    observed_generation: i64,
    #[serde(skip_serializing_if = "is_zero_i32")]
    updated_number_scheduled: i32,
    #[serde(skip_serializing_if = "is_zero_i32")]
    number_available: i32,
    #[serde(skip_serializing_if = "is_zero_i32")]
    number_unavailable: i32,
    #[serde(skip_serializing_if = "Option::is_none")]
    collision_count: Option<i32>,
}

fn go_container(c: &Container) -> GoContainer<'_> {
    static EMPTY: ResourceRequirements = ResourceRequirements {
        claims: None,
        limits: None,
        requests: None,
    };
    let res = c.resources.as_ref().unwrap_or(&EMPTY);
    GoContainer {
        name: &c.name,
        image: &c.image,
        command: &c.command,
        args: &c.args,
        resources: GoResources {
            limits: &res.limits,
            requests: &res.requests,
        },
        termination_message_path: &c.termination_message_path,
        termination_message_policy: &c.termination_message_policy,
        image_pull_policy: &c.image_pull_policy,
    }
}

fn go_toleration(t: &Toleration) -> GoToleration<'_> {
    GoToleration {
        key: &t.key,
        operator: &t.operator,
        value: &t.value,
        effect: &t.effect,
        toleration_seconds: t.toleration_seconds,
    }
}

fn go_pod_spec(p: &PodSpec) -> GoPodSpec<'_> {
    GoPodSpec {
        containers: Some(p.containers.iter().map(go_container).collect()),
        restart_policy: &p.restart_policy,
        termination_grace_period_seconds: p.termination_grace_period_seconds,
        dns_policy: &p.dns_policy,
        node_selector: &p.node_selector,
        service_account_name: &p.service_account_name,
        host_network: p.host_network.unwrap_or(false),
        scheduler_name: &p.scheduler_name,
        tolerations: p
            .tolerations
            .as_ref()
            .map(|t| t.iter().map(go_toleration).collect()),
        priority_class_name: &p.priority_class_name,
        priority: p.priority,
    }
}

fn go_label_selector(s: &LabelSelector) -> GoLabelSelector<'_> {
    GoLabelSelector {
        match_labels: &s.match_labels,
        match_expressions: s
            .match_expressions
            .as_ref()
            .map(|e| e.iter().map(|e| serde_json::to_value(e).unwrap()).collect()),
    }
}

fn go_daemon_set(ds: &DaemonSet) -> String {
    let spec = ds.spec.clone().unwrap_or_default();
    let status = ds.status.clone().unwrap_or_default();
    let tmpl_meta = spec.template.metadata.clone().unwrap_or_default();
    let pod_spec = spec.template.spec.clone().unwrap_or_default();
    let strategy = spec.update_strategy.clone().unwrap_or_default();
    let out = serde_json::to_string(&GoDaemonSet {
        metadata: apis::go::Go(&ds.metadata),
        spec: GoDaemonSetSpec {
            selector: go_label_selector(&spec.selector),
            template: GoPodTemplateSpec {
                metadata: apis::go::Go(&tmpl_meta),
                spec: go_pod_spec(&pod_spec),
            },
            update_strategy: GoUpdateStrategy {
                type_: strategy.type_.clone(),
                rolling_update: strategy
                    .rolling_update
                    .as_ref()
                    .map(|r| serde_json::to_value(r).unwrap()),
            },
            min_ready_seconds: spec.min_ready_seconds.unwrap_or(0),
            revision_history_limit: spec.revision_history_limit,
        },
        status: GoDaemonSetStatus {
            current_number_scheduled: status.current_number_scheduled,
            number_misscheduled: status.number_misscheduled,
            desired_number_scheduled: status.desired_number_scheduled,
            number_ready: status.number_ready,
            observed_generation: status.observed_generation.unwrap_or(0),
            updated_number_scheduled: status.updated_number_scheduled.unwrap_or(0),
            number_available: status.number_available.unwrap_or(0),
            number_unavailable: status.number_unavailable.unwrap_or(0),
            collision_count: status.collision_count,
        },
    })
    .unwrap();
    assert_lossless::<DaemonSet>(ds, &out);
    out
}

/// Drop Go zero values (null, "", 0, false, {}, []) recursively.
fn strip_zero(v: Value) -> Value {
    match v {
        Value::Object(m) => Value::Object(
            m.into_iter()
                .map(|(k, v)| (k, strip_zero(v)))
                .filter(|(_, v)| !is_zero(v))
                .collect(),
        ),
        Value::Array(a) => Value::Array(a.into_iter().map(strip_zero).collect()),
        other => other,
    }
}
fn is_zero(v: &Value) -> bool {
    match v {
        Value::Null => true,
        Value::Bool(b) => !b,
        Value::Number(n) => n.as_f64() == Some(0.0),
        Value::String(s) => s.is_empty(),
        Value::Array(a) => a.is_empty(),
        Value::Object(o) => o.is_empty(),
    }
}

/// The Go-order mirror must not drop any non-zero data of the object.
fn assert_lossless<K>(obj: &K, go_json: &str)
where
    K: Serialize + for<'de> Deserialize<'de>,
{
    let back: K = serde_json::from_str(go_json).unwrap();
    assert_eq!(
        strip_zero(serde_json::to_value(&back).unwrap()),
        strip_zero(serde_json::to_value(obj).unwrap()),
        "Go mirror encoding dropped data: {go_json}"
    );
}

// --- fakes ----------------------------------------------------------------------------------

struct FakeReader {
    results: BTreeMap<String, (String, String)>,
    calls: Mutex<Vec<String>>,
}

#[async_trait]
impl ReleaseImageReader for FakeReader {
    async fn get_component_image(
        &self,
        _ctx: &Ctx,
        release_image_ref: &str,
        component_name: &str,
        _keychain: Arc<dyn Keychain>,
    ) -> Result<String> {
        self.calls
            .lock()
            .unwrap()
            .push(format!("{release_image_ref} {component_name}"));
        let (image, err) = self
            .results
            .get(release_image_ref)
            .cloned()
            .unwrap_or_default();
        if !err.is_empty() {
            return Err(anyhow::anyhow!("{}", err));
        }
        Ok(image)
    }
}

/// Records `V<level> <name>: <msg> <json [k, v, ...]>` like the Go generator's sink.
#[derive(Default)]
struct Capture {
    lines: Mutex<Vec<String>>,
}

fn kvs_json(kvs: &[(String, Value)]) -> String {
    let flat: Vec<Value> = kvs
        .iter()
        .flat_map(|(k, v)| [Value::String(k.clone()), v.clone()])
        .collect();
    serde_json::to_string(&flat).unwrap()
}

impl LogSink for Capture {
    fn enabled(&self, _level: i32) -> bool {
        true
    }
    fn info(&self, level: i32, name: &str, msg: &str, kvs: &[(String, Value)]) {
        self.lines
            .lock()
            .unwrap()
            .push(format!("V{level} {name}: {msg} {}", kvs_json(kvs)));
    }
    fn error(&self, err: Option<&str>, name: &str, msg: &str, kvs: &[(String, Value)]) {
        let mut kvs: KeyValues = kvs.to_vec();
        kvs.push(("error".into(), Value::String(err.unwrap_or("<nil>").into())));
        self.lines
            .lock()
            .unwrap()
            .push(format!("E {name}: {msg} {}", kvs_json(&kvs)));
    }
}

fn pull_secret(kind: &str) -> Option<Secret> {
    let meta = ObjectMeta {
        name: Some("pull-secret".into()),
        namespace: Some(CR_NAMESPACE.into()),
        ..Default::default()
    };
    match kind {
        "valid" => Some(Secret {
            metadata: meta,
            data: Some(BTreeMap::from([(
                ".dockerconfigjson".into(),
                ByteString(br#"{"auths":{}}"#.to_vec()),
            )])),
            type_: Some("kubernetes.io/dockerconfigjson".into()),
            ..Default::default()
        }),
        "nokey" => Some(Secret {
            metadata: meta,
            data: Some(BTreeMap::from([(
                "other".into(),
                ByteString(b"x".to_vec()),
            )])),
            ..Default::default()
        }),
        _ => None,
    }
}

fn provisioner(release: &str) -> DPFHCPProvisioner {
    DPFHCPProvisioner {
        metadata: ObjectMeta {
            name: Some(CR_NAME.into()),
            namespace: Some(CR_NAMESPACE.into()),
            ..Default::default()
        },
        spec: DPFHCPProvisionerSpec {
            ocp_release_image: release.into(),
            pull_secret_ref: apis::k8s::core::v1::LocalObjectReference {
                name: "pull-secret".into(),
                ..Default::default()
            },
            ..Default::default()
        },
        ..Default::default()
    }
}

// --- runner ---------------------------------------------------------------------------------

async fn run(name: &str) {
    let sc = fixture(name);
    let ctx = Ctx::background();

    let mut mgmt = FakeClientBuilder::new().with_scheme(
        Scheme::new()
            .register::<Secret>()
            .register::<DPFHCPProvisioner>(),
    );
    if let Some(s) = pull_secret(&sc.pull_secret) {
        mgmt = mgmt.with_object(&s);
    }
    let mgmt = mgmt.build();

    let seeds: Vec<Namespace> = sc
        .seed_namespaces
        .iter()
        .map(|v| serde_json::from_value(v.clone()).unwrap())
        .collect();
    let mut builder = FakeClientsetBuilder::new();
    for ns in &seeds {
        builder = builder.with_object(ns);
    }
    let backend: FakeClientset = builder.build_fake();
    let fail: Arc<Mutex<Option<Fail>>> = Arc::default();
    {
        let fail = fail.clone();
        backend.prepend_reactor("*", "*", move |a| match &*fail.lock().unwrap() {
            Some(f) if a.matches(&f.verb, &f.resource) => {
                Reaction::error(ApiError::bad_request(f.message.clone()))
            }
            _ => Reaction::NotHandled,
        });
    }
    let hosted = HostedClient::fake(backend.client());
    // Direct (unfailing) access to the hosted fake for setup and dumps.
    let direct = HostedClient::fake(backend.client());

    let cm = Arc::new(ClientManager::new(mgmt.clone()));
    if sc.inject_client {
        cm.set_hosted_cluster_client(CR_NAMESPACE, CR_NAME, hosted.clone());
    }
    let reader = Arc::new(FakeReader {
        results: sc
            .reader
            .iter()
            .map(|(k, v)| (k.clone(), (v.image.clone(), v.err.clone())))
            .collect(),
        calls: Mutex::default(),
    });
    let m = Manager::new(mgmt, cm.clone(), reader.clone());

    for (i, st) in sc.steps.iter().enumerate() {
        let what = format!("{name} step {i}");
        if st.reinject {
            cm.set_hosted_cluster_client(CR_NAMESPACE, CR_NAME, hosted.clone());
        }
        if let Some(v) = &st.replace_namespace {
            let ns: Namespace = serde_json::from_value(v.clone()).unwrap();
            direct
                .resource::<Namespace>("")
                .update(&ctx, &ns)
                .await
                .unwrap();
        }
        if let Some(v) = &st.replace_daemon_set {
            let ds: DaemonSet = serde_json::from_value(v.clone()).unwrap();
            direct
                .resource::<DaemonSet>(OVS_HUGEPAGES_NAMESPACE)
                .update(&ctx, &ds)
                .await
                .unwrap();
        }
        *fail.lock().unwrap() = st.fail.clone();
        reader.calls.lock().unwrap().clear();
        let capture = Arc::new(Capture::default());
        let lctx = ctx.with_logger(Logger::with_sink(capture.clone()));

        let res = m
            .reconcile_hugepages_daemon_set(&lctx, &provisioner(&st.release), &st.size, st.amount)
            .await;
        *fail.lock().unwrap() = None;

        // Go panics where Rust returns an error (see module docs); the message is the same.
        let error = res.err().map(|e| e.to_string()).unwrap_or_default();
        assert_eq!(error, st.error, "{what}: error (go panic: {})", st.panic);
        assert_eq!(
            cm.has_cached_client(CR_NAMESPACE, CR_NAME),
            st.cached,
            "{what}: cached"
        );
        assert_eq!(
            *reader.calls.lock().unwrap(),
            st.reader_calls.clone().unwrap_or_default(),
            "{what}: reader calls"
        );
        assert_eq!(
            *capture.lines.lock().unwrap(),
            st.logs.clone().unwrap_or_default(),
            "{what}: logs"
        );

        let ns = match direct
            .resource::<Namespace>("")
            .get(&ctx, OVS_HUGEPAGES_NAMESPACE)
            .await
        {
            Ok(ns) => go_namespace(&ns),
            Err(e) if is_not_found(&e) => String::new(),
            Err(e) => panic!("{e}"),
        };
        assert_eq!(ns, st.namespace, "{what}: namespace");
        let ds = match direct
            .resource::<DaemonSet>(OVS_HUGEPAGES_NAMESPACE)
            .get(&ctx, DAEMON_SET_NAME)
            .await
        {
            Ok(ds) => go_daemon_set(&ds),
            Err(e) if is_not_found(&e) => String::new(),
            Err(e) => panic!("{e}"),
        };
        assert_eq!(ds, st.daemon_set, "{what}: daemonset");
    }
}

macro_rules! golden {
    ($($name:ident),+ $(,)?) => {$(
        #[tokio::test]
        async fn $name() {
            run(stringify!($name)).await;
        }
    )+};
}

golden!(
    create_default,
    defaults_for_empty_size_and_negative_amount,
    custom_sizes,
    amount_and_image_change,
    drift_corrected,
    existing_namespace_labels_merged,
    disable_after_create,
    disabled_nothing_exists,
    aarch64_release,
    aarch64_reader_error,
    aarch64_empty_image,
    multi_reader_error,
    multi_empty_image,
    pull_secret_missing,
    pull_secret_missing_key,
    hosted_client_unavailable,
    namespace_get_fails,
    namespace_create_fails,
    namespace_update_fails,
    daemonset_create_fails,
    daemonset_get_fails,
    daemonset_update_fails,
    daemonset_delete_fails,
    invalid_size,
);

/// Every fixture file has a test above.
#[test]
fn every_fixture_is_tested() {
    let dir = format!("{}/tests/fixtures", env!("CARGO_MANIFEST_DIR"));
    let mut names: Vec<String> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .filter(|n| n.ends_with(".json") && n != "quantities.json")
        .collect();
    names.sort();
    assert_eq!(names.len(), 24, "{names:?}");
}
